class TestSemanticCacheGetPut:
    """[P0] Tests for get and put operations."""

    @pytest.fixture()
    def semantic_cache(self):
        """Create SemanticCache instance."""
        return SemanticCache()

    @pytest.mark.asyncio
    async def test_put_and_get_exact_match(self, semantic_cache):
        """[P0] Should store and retrieve exact match from L1."""
        prompt = "What is AI?"
        response = "AI is artificial intelligence"
        system = ""
        model = "test-model"

        # Put entry
        await semantic_cache.put(prompt, response, system, model)

        # Get should return from L1
        result = await semantic_cache.get(prompt, system, model)
        assert result == response

    @pytest.mark.asyncio
    async def test_get_nonexistent_returns_none(self, semantic_cache):
        """[P0] Should return None for non-existent key."""
        result = await semantic_cache.get("nonexistent", "", "model")

        assert result is None

    @pytest.mark.asyncio
    async def test_get_increments_miss_count(self, semantic_cache):
        """[P0] Should increment miss count on cache miss."""
        await semantic_cache.get("new prompt", "", "model")

        stats = semantic_cache.get_stats()
        assert stats["misses"] >= 1

    @pytest.mark.asyncio
    async def test_get_increments_hit_count(self, semantic_cache):
        """[P0] Should increment hit count on cache hit."""
        prompt = "test prompt"
        await semantic_cache.put(prompt, "response", "", "model")

        # First get
        await semantic_cache.get(prompt, "", "model")

        # Second get should be L1 hit
        await semantic_cache.get(prompt, "", "model")

        stats = semantic_cache.get_stats()
        assert stats["l1_hits"] >= 1


