class TestSemanticCacheIntegration:
    """[P1] Integration tests for semantic cache."""

    @pytest.mark.fast
    @pytest.mark.asyncio
    @requires_real_st
    async def test_cache_workflow(self):
        """[P0] Should demonstrate complete cache workflow."""
        cache = SemanticCache(similarity_threshold=0.88)

        # Put some entries
        await cache.put("What is Python?", "Python is a language", "", "model")
        await cache.put("What is FastAPI?", "FastAPI is a framework", "", "model")

        # Get exact match
        result1 = await cache.get("What is Python?", "", "model")
        assert result1 == "Python is a language"

        # Get non-existent
        result2 = await cache.get("What is Django?", "", "model")
        assert result2 is None

        # Check stats
        stats = cache.get_stats()
        assert stats["l1_hits"] + stats["l2_hits"] >= 1
        assert stats["misses"] >= 1

        # Clear
        cache.clear()
        stats = cache.get_stats()
        assert stats["l1_hits"] == 0
        assert stats["l2_hits"] == 0


