# Access Entropy diagnostic (AE1–AE5, 2026-07-04)
# ---------------------------------------------------------------------------


class TestAccessEntropy:
    """access_entropy() diagnostic — Shannon entropy of rolling access window.

    Distinguishes entropy-driven miss rates (high H → diverse workload, natural)
    from threshold misconfiguration (low H → repetitive workload, misses = alert).

    AE1: returns 0.0 when window has <2 entries
    AE2: DISCRIMINATING — low entropy for repetitive access pattern (same key always)
    AE3: DISCRIMINATING — high entropy for fully-diverse access pattern (all unique keys)
    AE4: get_stats() includes 'access_entropy' and 'combined_hit_rate' keys
    AE5: clear() resets the access window (entropy returns to 0.0)
    """

    def _make_cache(self) -> SemanticCache:
        return SemanticCache.__new__(SemanticCache)

    def _inject_window(self, cache: SemanticCache, keys: list) -> None:
        """Directly populate the access window without calling get()."""
        from collections import deque

        cache._access_window = deque(keys, maxlen=256)

    # ── AE1 ──────────────────────────────────────────────────────────────

    def test_ae1_empty_window_returns_zero(self) -> None:
        """AE1: fewer than 2 entries → 0.0 (not meaningful yet)."""
        cache = SemanticCache()
        assert cache.access_entropy() == pytest.approx(0.0)

        # Inject a single key — still < 2 entries
        cache._access_window.append("abc")
        assert cache.access_entropy() == pytest.approx(0.0)

    # ── AE2 discriminating — low entropy ─────────────────────────────────

    def test_ae2_repetitive_access_gives_low_entropy(self) -> None:
        """AE2 discriminating: same key repeated → entropy near 0.0.

        Wrong impl returning constant 0.5 would FAIL (doesn't discriminate).
        Wrong impl always returning 1.0 would FAIL (can't distinguish extremes).
        """
        cache = SemanticCache()
        # All 20 accesses are the same key
        self._inject_window(cache, ["aaaa1111"] * 20)
        entropy = cache.access_entropy()
        # H = 0 (all mass on one key), normalized = 0 / log2(20) = 0
        assert entropy == pytest.approx(0.0, abs=1e-9), (
            f"Repetitive access must give entropy≈0, got {entropy:.4f}"
        )

    # ── AE3 discriminating — high entropy ────────────────────────────────

    def test_ae3_diverse_access_gives_high_entropy(self) -> None:
        """AE3 discriminating: all unique keys → entropy near 1.0.

        Wrong impl returning constant 0.0 would FAIL.
        Wrong impl returning 0.5 always would FAIL (below 0.9).
        """
        cache = SemanticCache()
        # 32 unique keys → uniform distribution → H = log2(32) = 5 bits
        unique_keys = [f"key{i:04d}" for i in range(32)]
        self._inject_window(cache, unique_keys)
        entropy = cache.access_entropy()
        # H / log2(32) = 5/5 = 1.0 exactly for uniform distribution
        assert entropy > 0.9, (
            f"Fully diverse access must give entropy > 0.9, got {entropy:.4f}"
        )

    def test_ae3_entropy_strictly_higher_for_diverse_vs_repetitive(self) -> None:
        """AE3 discriminating (relative): diverse > repetitive (same window size).

        This is the core discriminating invariant — an impl returning a constant
        for both would FAIL.
        """
        cache = SemanticCache()
        # Repetitive: 2 keys alternating
        self._inject_window(cache, ["aaa"] * 50 + ["bbb"] * 50)
        low_entropy = cache.access_entropy()

        # Diverse: 100 unique keys
        unique_keys = [f"k{i:05d}" for i in range(100)]
        self._inject_window(cache, unique_keys)
        high_entropy = cache.access_entropy()

        assert high_entropy > low_entropy, (
            f"Diverse entropy {high_entropy:.4f} must exceed repetitive {low_entropy:.4f}"
        )

    # ── AE4 get_stats() integration ──────────────────────────────────────

    def test_ae4_get_stats_includes_required_keys(self) -> None:
        """AE4: get_stats() must include 'access_entropy' and 'combined_hit_rate'."""
        cache = SemanticCache()
        stats = cache.get_stats()
        assert "access_entropy" in stats, (
            "get_stats() must include 'access_entropy' for DegradationDetector integration"
        )
        assert "combined_hit_rate" in stats, (
            "get_stats() must include 'combined_hit_rate' (fraction, not %) for DegradationDetector"
        )

    def test_ae4_combined_hit_rate_is_fraction_not_percent(self) -> None:
        """AE4: combined_hit_rate must be [0,1] not [0,100]."""
        cache = SemanticCache()
        stats = cache.get_stats()
        # With no requests, combined_hit_rate should be 0.0 not NaN or 100.0
        assert 0.0 <= stats["combined_hit_rate"] <= 1.0, (
            f"combined_hit_rate must be a fraction [0,1], got {stats['combined_hit_rate']}"
        )

    # ── AE5 clear() resets window ────────────────────────────────────────

    def test_ae5_clear_resets_access_window(self) -> None:
        """AE5: clear() empties the access window so entropy returns to 0.0."""
        cache = SemanticCache()
        self._inject_window(cache, ["x"] * 30 + ["y"] * 30)
        assert cache.access_entropy() > 0.0  # precondition: window has data

        cache.clear()
        assert cache.access_entropy() == pytest.approx(0.0), (
            "After clear(), access window must be empty → entropy must be 0.0"
        )
